function injectProductLabelFields(){const form=$('#productEditForm');if(!form||form.querySelector('[data-label-meta-fields]'))return;const actions=form.querySelector('.dialog-actions');actions.insertAdjacentHTML('beforebegin',`<section class="product-label-meta" data-label-meta-fields><div class="product-label-meta-head"><div><h4>Этикетка, EAN и информация для Испании</h4><p>Основной язык обязательной информации — ES. Panora проверяет заполнение по правилам ЕС/Испании, но перед печатью позволяет подтвердить исключения вручную.</p></div><span>11.18</span></div><div class="settings-row"><label><span>Юридическое название ES</span><input name="labelLegalEs" maxlength="160"></label><label><span>Категория хлеба</span><select name="labelBreadClass"><option value="">Не выбрано · требуется проверка</option><option value="common">Pan común</option><option value="special">Pan especial</option><option value="other">Другое хлебобулочное изделие</option></select></label></div><div class="settings-row"><label><span>Юридическое название RU</span><input name="labelLegalRu" maxlength="160"></label><label><span>Юридическое название EN</span><input name="labelLegalEn" maxlength="160"></label></div><div class="product-label-law-checks"><label class="check"><input name="labelFresh24h" type="checkbox"><span>Изделие обычно потребляется в течение 24 ч после изготовления (дата минимальной годности может не требоваться)</span></label><label class="check"><input name="labelAllergensVerified" type="checkbox"><span>Аллергены EU-14 проверены и подтверждены</span></label></div><div class="settings-row"><label><span>GTIN / EAN-13 · для магазинов</span><input name="labelGtin" inputmode="numeric" maxlength="13" placeholder="12 или 13 цифр"><small>Официальный GTIN. Panora проверяет контрольную цифру, но не создаёт официальный номер.</small></label><label><span>Código interno / SKU · касса Panora</span><input name="labelSku" maxlength="40"><small>Внутренний код Panora; не заменяет GTIN/EAN-13 во внешней рознице.</small></label></div><div class="settings-row"><label><span>Вес нетто, г</span><input name="labelNetWeight" type="number" min="0" step="1" placeholder="По весу карточки"></label><label><span>Срок годности, дней</span><input name="labelShelfLife" type="number" min="0" step="1"></label></div><label><span>QUID / процент выделенного ингредиента (ES)</span><input name="labelQuidEs" maxlength="220" placeholder="Например: semillas de lino 8 %"><small>Нужен, когда ингредиент/злак/семя указан в названии или подчёркнут на этикетке, если не действует исключение.</small></label><label><span>Подтверждённые обозначения</span><input name="labelClaims" maxlength="220" placeholder="Например: elaborado con masa madre"><small>Термины integral, de elaboración artesana, masa madre, larga fermentación применяйте только при выполнении условий нормы качества хлеба.</small></label><div class="product-label-law-checks"><label class="check"><input name="labelArtisanVerified" type="checkbox"><span>Условия «de elaboración artesana» подтверждены</span></label><label class="check"><input name="labelSourdoughVerified" type="checkbox"><span>Условия «elaborado con masa madre» подтверждены</span></label><label class="check"><input name="labelLongFermentationVerified" type="checkbox"><span>Условия «larga fermentación» подтверждены</span></label></div><label><span>Ссылка товара / рекламы</span><input name="labelQrUrl" type="url" placeholder="https://…"></label><div class="settings-row"><label><span>Производитель / пекарня</span><input name="labelManufacturer" maxlength="180"></label><label><span>Площадь наибольшей поверхности упаковки, см²</span><input name="labelLargestSurfaceCm2" type="number" min="0" step="0.1" placeholder="Для контроля 1,2 / 0,9 мм x-height"></label></div><fieldset class="product-label-law-fieldset"><legend>Происхождение</legend><label class="check"><input name="labelOriginDeclared" type="checkbox"><span>Печатать страну происхождения / место происхождения</span></label><div class="settings-row"><label><span>Страна / место происхождения продукта</span><input name="labelCountry" maxlength="100" placeholder="Например: España"></label><label><span>Происхождение основного ингредиента</span><select name="labelPrimaryOriginMode"><option value="same">То же, что у продукта</option><option value="different">Другое</option><option value="unknown">Не заявляется / неизвестно</option></select></label></div><div class="settings-row"><label><span>Основной ингредиент</span><input name="labelPrimaryIngredientName" maxlength="120" placeholder="Например: harina de trigo"></label><label><span>Его происхождение</span><input name="labelPrimaryIngredientOrigin" maxlength="120" placeholder="Например: UE y no UE"></label></div></fieldset><div class="product-label-storage"><label><span>Conservación ES</span><textarea name="labelStorageEs" rows="2"></textarea></label><label><span>Хранение RU</span><textarea name="labelStorageRu" rows="2"></textarea></label><label><span>Storage EN</span><textarea name="labelStorageEn" rows="2"></textarea></label></div><fieldset class="product-label-nutrition"><legend>Información nutricional / 100 g</legend><label class="check product-label-nutrition-exempt"><input name="labelNutritionExemptLocal" type="checkbox"><span>Исключение: небольшие количества напрямую от производителя конечному покупателю / местной рознице, которая снабжает конечного покупателя</span></label><div class="product-label-nutrition-grid"><label><span>кДж</span><input name="nutKj" type="number" min="0" step="1"></label><label><span>ккал</span><input name="nutKcal" type="number" min="0" step="1"></label><label><span>Жиры, г</span><input name="nutFat" type="number" min="0" step="0.1"></label><label><span>Насыщенные, г</span><input name="nutSat" type="number" min="0" step="0.1"></label><label><span>Углеводы, г</span><input name="nutCarbs" type="number" min="0" step="0.1"></label><label><span>Сахара, г</span><input name="nutSugars" type="number" min="0" step="0.1"></label><label><span>Белки, г</span><input name="nutProtein" type="number" min="0" step="0.1"></label><label><span>Соль, г</span><input name="nutSalt" type="number" min="0" step="0.01"></label></div></fieldset><fieldset class="product-label-law-fieldset"><legend>Упаковка и отходы · Испания</legend><div class="settings-row"><label><span>Материал упаковки</span><select name="labelPackagingMaterial"><option value="">Не выбран</option><option value="paper">Бумага / картон</option><option value="plastic">Пластик</option><option value="glass">Стекло</option><option value="metal">Металл</option><option value="compostable">Компостируемый пластик</option><option value="composite">Комбинированный</option><option value="other">Другое</option></select></label><label><span>Куда выбрасывать</span><select name="labelWasteFraction"><option value="">Не выбрано</option><option value="blue">Contenedor azul · papel/cartón</option><option value="yellow">Contenedor amarillo · envases</option><option value="green">Contenedor verde · vidrio</option><option value="brown">Contenedor marrón · biorresiduos</option><option value="rest">Fracción resto</option><option value="custom">Другая система / местная инструкция</option></select></label></div><div class="settings-row"><label><span>Где сообщать об утилизации</span><select name="labelWasteInfoMode"><option value="label">На упаковке / этикетке</option><option value="point">В точке продажи</option></select></label><label><span>Текст утилизации ES</span><input name="labelWasteTextEs" maxlength="180" placeholder="Например: Depositar en el contenedor azul"></label></div><div class="product-label-law-checks"><label class="check"><input name="labelCompostableCertified" type="checkbox"><span>Для compostable: сертификация UNE EN 13432 / применимый стандарт подтверждена</span></label></div></fieldset><div class="product-label-safety-status" id="productLabelSafetyStatus"></div></section>`)}
function fillProductLabelFields(id){const form=$('#productEditForm');if(!form)return;const p=productRegistry.find(x=>x.id===id),card=technicalCard(id),m=card.labelMeta||{},n=m.nutrition||{},bakery=bakeryProfile();const set=(name,val)=>{if(form.elements[name])form.elements[name].value=val??''},check=(name,val)=>{if(form.elements[name])form.elements[name].checked=val===true};set('labelLegalEs',m.legalNames?.es||p?.names?.es||'');set('labelLegalRu',m.legalNames?.ru||p?.names?.ru||'');set('labelLegalEn',m.legalNames?.en||p?.names?.en||'');set('labelBreadClass',m.breadClass||'');check('labelFresh24h',m.fresh24h===true);set('labelGtin',m.gtin||'');set('labelSku',m.sku||card.sku||p?.sku||defaultInternalCode(id));set('labelNetWeight',m.netWeightG||'');set('labelShelfLife',card.shelfLifeDays||m.shelfLifeDays||'');set('labelQuidEs',m.quidEs||'');check('labelAllergensVerified',m.allergensVerified===true);set('labelQrUrl',m.qrUrl||'');set('labelClaims',m.claims||'');check('labelArtisanVerified',m.artisanVerified===true);check('labelSourdoughVerified',m.sourdoughVerified===true);check('labelLongFermentationVerified',m.longFermentationVerified===true);set('labelManufacturer',card.manufacturer||bakery.legalName||'');set('labelLargestSurfaceCm2',m.largestSurfaceCm2||'');check('labelOriginDeclared',m.originDeclared===true);set('labelCountry',card.country||m.country||'');set('labelPrimaryOriginMode',m.primaryOriginMode||'same');set('labelPrimaryIngredientName',m.primaryIngredientName||'');set('labelPrimaryIngredientOrigin',m.primaryIngredientOrigin||'');set('labelStorageEs',card.storageEs||'');set('labelStorageRu',card.storageRu||'');set('labelStorageEn',card.storageEn||'');check('labelNutritionExemptLocal',m.nutritionExemptLocal===true);set('labelPackagingMaterial',m.packagingMaterial||'');set('labelWasteFraction',m.wasteFraction||'');set('labelWasteInfoMode',m.wasteInfoMode||'label');set('labelWasteTextEs',m.wasteTextEs||'');check('labelCompostableCertified',m.compostableCertified===true);[['nutKj','kj'],['nutKcal','kcal'],['nutFat','fat'],['nutSat','saturates'],['nutCarbs','carbs'],['nutSugars','sugars'],['nutProtein','protein'],['nutSalt','salt']].forEach(([field,key])=>set(field,n[key]??''));const status=$('#productLabelSafetyStatus'),comp=composition(id,'es'),alls=productAllergens(id);if(status)status.innerHTML=`<strong>${comp?'ES: состав заполнен':'⚠ ES: состав не заполнен'}</strong><span>${m.allergensVerified===true?'Аллергены проверены ✓':'⚠ подтвердите аллергены'}${alls.length?` · ${alls.map(x=>allergenName(x,'es')).join(', ')}`:''}</span><span>${m.fresh24h===true?'Режим ≤24 ч':'Обычный срок'}</span>`}
function captureProductLabelFields(form){const f=new FormData(form);return{legalNames:{es:String(f.get('labelLegalEs')||'').trim(),ru:String(f.get('labelLegalRu')||'').trim(),en:String(f.get('labelLegalEn')||'').trim()},breadClass:String(f.get('labelBreadClass')||''),fresh24h:f.get('labelFresh24h')==='on',gtin:String(f.get('labelGtin')||'').replace(/\s/g,''),sku:String(f.get('labelSku')||'').trim(),netWeightG:Math.max(0,num(f.get('labelNetWeight')))||0,shelfLifeDays:Math.max(0,Math.floor(num(f.get('labelShelfLife')))),quidEs:String(f.get('labelQuidEs')||'').trim(),allergensVerified:f.get('labelAllergensVerified')==='on',qrUrl:String(f.get('labelQrUrl')||'').trim(),claims:String(f.get('labelClaims')||'').trim(),artisanVerified:f.get('labelArtisanVerified')==='on',sourdoughVerified:f.get('labelSourdoughVerified')==='on',longFermentationVerified:f.get('labelLongFermentationVerified')==='on',manufacturer:String(f.get('labelManufacturer')||'').trim(),largestSurfaceCm2:Math.max(0,num(f.get('labelLargestSurfaceCm2')))||0,originDeclared:f.get('labelOriginDeclared')==='on',country:String(f.get('labelCountry')||'').trim(),primaryOriginMode:String(f.get('labelPrimaryOriginMode')||'same'),primaryIngredientName:String(f.get('labelPrimaryIngredientName')||'').trim(),primaryIngredientOrigin:String(f.get('labelPrimaryIngredientOrigin')||'').trim(),storageEs:String(f.get('labelStorageEs')||'').trim(),storageRu:String(f.get('labelStorageRu')||'').trim(),storageEn:String(f.get('labelStorageEn')||'').trim(),nutritionExemptLocal:f.get('labelNutritionExemptLocal')==='on',packagingMaterial:String(f.get('labelPackagingMaterial')||''),wasteFraction:String(f.get('labelWasteFraction')||''),wasteInfoMode:String(f.get('labelWasteInfoMode')||'label'),wasteTextEs:String(f.get('labelWasteTextEs')||'').trim(),compostableCertified:f.get('labelCompostableCertified')==='on',nutrition:{kj:f.get('nutKj')===''?'':Math.max(0,num(f.get('nutKj'))),kcal:f.get('nutKcal')===''?'':Math.max(0,num(f.get('nutKcal'))),fat:f.get('nutFat')===''?'':Math.max(0,num(f.get('nutFat'))),saturates:f.get('nutSat')===''?'':Math.max(0,num(f.get('nutSat'))),carbs:f.get('nutCarbs')===''?'':Math.max(0,num(f.get('nutCarbs'))),sugars:f.get('nutSugars')===''?'':Math.max(0,num(f.get('nutSugars'))),protein:f.get('nutProtein')===''?'':Math.max(0,num(f.get('nutProtein'))),salt:f.get('nutSalt')===''?'':Math.max(0,num(f.get('nutSalt')))}}}
function wireProductEditor(){injectProductLabelFields();if(typeof openProductEditor==='function'){const base=openProductEditor;openProductEditor=function(id=''){base(id);requestAnimationFrame(()=>fillProductLabelFields(id))}}const form=$('#productEditForm');if(form?.onsubmit&&!form.dataset.labelMetaWrapped){const base=form.onsubmit;form.onsubmit=async function(e){if(!form.productId.value)form.productId.value=`bread-${Date.now()}`;const id=form.productId.value,data=captureProductLabelFields(form);await base.call(this,e);if(!$('#productEditDialog')?.open&&productRegistry.some(x=>String(x.id)===String(id)))saveLabelMeta(id,data);renderLabelBuilder()};form.dataset.labelMetaWrapped='1'}}
function sizeRank(size){return({'58x40':1,'70x50':2,'100x50':3,'100x70':4,'58x160':5,'custom':99})[String(size||'')]||0}
function minimumSizeForTemplate(template){return template==='vertical'?'58x160':template==='full'?'100x50':template==='package'?'70x50':'58x40'}
function normalizeTemplateSize(){builder.customWidth=clamp(builder.customWidth||presetDimensions(builder.size).w,10,210);builder.customHeight=clamp(builder.customHeight||presetDimensions(builder.size).h,10,300);if(!builder.size)builder.size='custom'}
function builderDimensions(){normalizeTemplateSize();return{w:clamp(builder.customWidth,10,210),h:clamp(builder.customHeight,10,300)}}
function resizePhysicalLabel(width,height){const oldKey=layoutKey(),oldLayout=currentLayout()?structuredClone(currentLayout()):null;builder.customWidth=clamp(width,10,210);builder.customHeight=clamp(height,10,300);builder.size='custom';const newKey=layoutKey();if(oldLayout&&oldKey!==newKey&&!ensureLayouts()[newKey]){ensureLayouts()[newKey]=oldLayout;ensureLayouts()[newKey].updatedAt=new Date().toISOString()}builder.selectedBlock=preferredBlockId(currentLayout());builder.richEditBlock='';builder.richEditProductId='';saveBuilder()}
function applySizePreset(size){const d=presetDimensions(size);builder.size=size;builder.customWidth=d.w;builder.customHeight=d.h;builder.selectedBlock='';builder.richEditBlock='';builder.richEditProductId='';saveBuilder()}
function autoDefaultsForTemplate(value){builder.template=value;builder.layoutEdit=false;builder.selectedBlock='';builder.richEditBlock='';builder.richEditProductId='';let preset='58x40';if(value==='shelf'){preset='58x40';builder.showPrice=true;builder.showBarcode=false;builder.showQr=true}if(value==='package'){preset='100x70';builder.showBarcode=true;builder.showQr=true}if(value==='full'){preset='100x70';builder.showBarcode=true;builder.showQr=true}if(value==='vertical'){preset='58x160';builder.showBarcode=true;builder.showQr=true}builder.size=preset;const d=presetDimensions(preset);builder.customWidth=d.w;builder.customHeight=d.h}
function productRowsHtml(){return productList().map(p=>{const row=builder.products[p.id]||{selected:false,qty:1},m=labelMeta(p.id),code=normalizeEan(m.gtin),lot=row.lot||latestLot(p.id,builder.bakeDate),card=technicalCard(p.id),best=m.fresh24h===true?(row.bestBefore||''):(row.bestBefore||addDays(builder.bakeDate,card.shelfLifeDays));return `<div class="pl-product-row" data-label-product-row="${esc(p.id)}"><label class="pl-product-check"><input type="checkbox" data-pl-field="selected" ${row.selected?'checked':''}><span><strong>${esc(productLabel(p.id,'es'))}</strong><small>${code?`GTIN ${code}`:'GTIN no indicado'} · Caja ${esc(internalProductCode(p,m,card))} · ${Number(m.netWeightG||p.weight||0)} g${m.fresh24h===true?' · ≤24 h':''}</small></span></label><label><span>Наклеек</span><input type="number" min="1" max="500" step="1" data-pl-field="qty" value="${Math.max(1,Number(row.qty||1))}"></label><label><span>Lote</span><input data-pl-field="lot" value="${esc(lot)}" placeholder="Можно не указывать при полной дате"></label><label><span>Duración mínima · если нужна</span><input type="date" data-pl-field="bestBefore" value="${esc(best)}"></label></div>`}).join('')}
function nutritionComplete(n={}){const required=['fat','saturates','carbs','sugars','protein','salt'];return num(n.kj)>0&&num(n.kcal)>0&&required.every(k=>n[k]!==undefined&&n[k]!==null&&String(n[k]).trim()!=='')}
function needsQuid(p){const m=labelMeta(p.id),name=String(m.legalNames?.es||p.names?.es||'').toLowerCase();return ['lino','semilla','calabaza','sésamo','sesamo','centeno','avena','espelta','nuez','nueces','aceituna','queso','chocolate','cebolla','ajo'].some(x=>name.includes(x))}
function dateCoversLot(day){return /^\d{4}-\d{2}-\d{2}$/.test(String(day||''))}
function dayAge(day){if(!day)return 0;const a=new Date(`${day}T12:00:00`),b=new Date(`${isoDay()}T12:00:00`);return Math.floor((b-a)/86400000)}
function legalXHeightRequired(m={}){const area=num(m.largestSurfaceCm2);return area>0&&area<80?.9:1.2}
function estimatedXHeight(fontMm,family='Manrope'){const ratio=safeFontFamily(family)==='Prata'?.48:safeFontFamily(family)==='Arial'?.52:.54;return num(fontMm)*ratio}
function wasteFractionText(m={}){if(String(m.wasteTextEs||'').trim())return String(m.wasteTextEs).trim();return({blue:'Depositar en el contenedor azul',yellow:'Depositar en el contenedor amarillo',green:'Depositar en el contenedor verde',brown:'Depositar en el contenedor marrón',rest:'Depositar en la fracción resto',custom:'Consultar la indicación local de recogida'})[m.wasteFraction]||''}
function packagingWasteHtml(m={},lang='es'){if(lang!=='es'||m.wasteInfoMode==='point')return'';const text=wasteFractionText(m),comp=m.packagingMaterial==='compostable';if(!text&&!comp)return'';return `<div class="pl-packaging-info"${blockAttrs('packaging','Envase · residuos')}>${text?`<p><b>Envase:</b> ${esc(text)}</p>`:''}${comp?'<p><b>Compostable:</b> no abandonar en el entorno.</p>':''}</div>`}
function claimComplianceIssues(p,m={}){const out=[],name=String(m.legalNames?.es||p.names?.es||'').toLowerCase(),claims=String(m.claims||'').toLowerCase(),tagline=String(labelProfile()?.tagline||'').toLowerCase(),all=`${name} ${claims} ${tagline}`;if(/artesan/.test(all)&&m.artisanVerified!==true)out.push('используется «artesana/artesano», но условия elaboración artesana не подтверждены');if(/masa madre/.test(all)&&m.sourdoughVerified!==true)out.push('используется «masa madre», но условия этой маркировки не подтверждены');if(/larga fermentaci[oó]n/.test(all)&&m.longFermentationVerified!==true)out.push('используется «larga fermentación», но условия ≥8 h не подтверждены');if(/integral|grano entero/.test(all)&&!String(m.quidEs||'').trim())out.push('для «integral / grano entero» проверьте требуемый процент муки, если продукт не 100 % integral');return out}
function legalLayoutWarnings(){const out=[],layout=currentLayout();if(builder.template==='shelf'||!layout?.blocks)return out;const selected=productList().filter(p=>builder.products[p.id]?.selected);for(const p of selected){const m=labelMeta(p.id),req=legalXHeightRequired(m);for(const id of ['title','ingredients','meta','producer','nutrition','packaging']){const b=layout.blocks[id];if(!b||b.hidden||b.deleted)continue;const xh=estimatedXHeight(b.fontSize,b.fontFamily);if(xh+0.02<req)out.push(`${productLabel(p.id,'es')}: блок «${b.label||id}» — расчётная x-height ≈ ${xh.toFixed(2)} мм, ориентир минимум ${req.toFixed(1)} мм.`)}const title=layout.blocks.title,meta=layout.blocks.meta;if(!title||title.hidden||title.deleted)out.push(`${productLabel(p.id,'es')}: на упаковке скрыто юридическое название.`);if(!meta||meta.hidden||meta.deleted)out.push(`${productLabel(p.id,'es')}: на упаковке скрыт блок с Peso neto.`)}return out}
function validationIssues(){
 const errors=[],blocking=[],warningsOut=[],selected=productList().filter(p=>builder.products[p.id]?.selected),bakery=bakeryProfile(),packaging=builder.template!=='shelf',prepacked=packaging&&builder.packageMode==='prepacked';
 if(!selected.length)blocking.push('Выберите хотя бы один товар.');
 if(builder.language!=='es')warningsOut.push('Для продажи в Испании обязательная информация должна присутствовать как минимум на испанском. RU/EN используйте только дополнительно к ES.');
 selected.forEach(p=>{const m=labelMeta(p.id),card=technicalCard(p.id),row=builder.products[p.id]||{},label=productLabel(p.id,'es'),weight=Math.max(0,num(m.netWeightG||p.weight)),best=m.fresh24h===true?(row.bestBefore||''):(row.bestBefore||addDays(builder.bakeDate,card.shelfLifeDays)),lot=String(row.lot||latestLot(p.id,builder.bakeDate)||'').trim(),alls=productAllergens(p.id),claims=claimComplianceIssues(p,m);if(!String(m.legalNames?.es||p.names?.es||'').trim())errors.push(`${label}: не заполнено испанское юридическое наименование.`);if(!String(m.breadClass||'').trim())errors.push(`${label}: не выбрана юридическая категория хлеба / хлебобулочного изделия.`);if(num(p.basePrice)<=0&&builder.template==='shelf')errors.push(`${label}: не указана конечная цена продажи.`);if(weight<=0)errors.push(`${label}: не указан вес / Peso neto.`);if(m.allergensVerified!==true)errors.push(`${label}: аллергены EU-14 не подтверждены.`);if(needsQuid(p)&&!String(m.quidEs||'').trim())errors.push(`${label}: название/акцент выделяет ингредиент — проверьте и заполните QUID / процент.`);claims.forEach(x=>errors.push(`${label}: ${x}.`));if(packaging&&!composition(p.id,'es'))errors.push(`${label}: заполните Ingredientes ES в «Производство и безопасность».`);if(packaging&&m.fresh24h!==true&&!best)errors.push(`${label}: не указана fecha de duración mínima / caducidad.`);if(packaging&&!String(card.storageEs||'').trim())warningsOut.push(`${label}: Conservación не заполнена. Она обязательна, когда условия нужны для сохранения указанного срока.`);if(prepacked&&!lot&&!dateCoversLot(best))errors.push(`${label}: нет Lote и нет даты с днём+месяцем, которая могла бы заменить указание партии.`);if(prepacked&&!nutritionComplete(m.nutrition||{})&&m.nutritionExemptLocal!==true)errors.push(`${label}: заполните Información nutricional / 100 g или подтвердите применимое исключение для малых прямых местных поставок.`);if(prepacked&&m.nutritionExemptLocal===true)warningsOut.push(`${label}: применено исключение от nutrition declaration — подтвердите, что поставки действительно небольшие, прямые и местные.`);if(builder.showBarcode&&!normalizeEan(m.gtin))errors.push(`${label}: включён EAN-13, но GTIN отсутствует или неверен.`);if(!alls.length&&m.allergensVerified===true)warningsOut.push(`${label}: отмечено отсутствие аллергенов EU-14 — проверьте рецептуру и возможные перекрёстные следы.`);if(m.originDeclared===true&&!String(card.country||m.country||'').trim())errors.push(`${label}: включено происхождение, но страна/место не заполнены.`);if(m.originDeclared===true&&m.primaryOriginMode==='different'&&(!String(m.primaryIngredientName||'').trim()||!String(m.primaryIngredientOrigin||'').trim()))errors.push(`${label}: происхождение основного ингредиента отличается — укажите ингредиент и его происхождение.`);if(packaging&&m.wasteInfoMode!=='point'&&!String(m.wasteFraction||'').trim())errors.push(`${label}: для бытовой упаковки не указана фракция/контейнер отходов.`);if(packaging&&m.wasteInfoMode==='point')warningsOut.push(`${label}: информация об утилизации выбрана «в точке продажи» — обеспечьте её заметное размещение там, где это допустимо для используемого типа упаковки.`);if(m.packagingMaterial==='compostable'&&m.compostableCertified!==true)errors.push(`${label}: упаковка отмечена как compostable, но подтверждение стандарта компостируемости не отмечено.`);if(String(m.breadClass||'')==='common'){const age=dayAge(builder.bakeDate);if(age>1)errors.push(`${label}: pan común выпечен более 24 ч назад — требуется отдельное размещение и явное информирование покупателя.`);else if(age===1)warningsOut.push(`${label}: pan común выпечен вчера — проверьте фактическое время, чтобы не превысить 24 ч.`)}});
 if(packaging&&!bakery.legalName)errors.push('В профиле пекарни не заполнено юридическое название оператора/упаковщика.');
 if(packaging&&!bakery.address)errors.push('В профиле пекарни не заполнен полный почтовый адрес оператора/упаковщика.');
 if(builder.size!=='custom'&&builder.template==='package'&&sizeRank(builder.size)<sizeRank('70x50'))warningsOut.push('Компактная упаковочная этикетка может не вместить обязательный текст с требуемой читаемостью.');
 if(prepacked&&builder.template!=='vertical'&&builderDimensions().w*builderDimensions().h<7000)warningsOut.push('Для полного preenvasado проверьте, что все обязательные данные помещаются без уменьшения шрифта ниже допустимого.');
 if(builder.showQr&&builder.template!=='vertical'&&!qrTarget(builder.qrMode,selected[0]?.id,labelProfile()))warningsOut.push('Для выбранного QR не заполнена ссылка.');
 errors.push(...legalLayoutWarnings());
 blocking.push(...layoutSafetyIssues());
 return{errors:[...new Set(errors)],blocking:[...new Set(blocking)],warnings:[...new Set(warningsOut)]}
}
function warnings(){const v=validationIssues();return[...(v.blocking||[]),...v.errors,...v.warnings]}

function profileHtml(){const p=labelProfile(),hasImage=Boolean(p.brandImage);return `<details class="pl-profile"><summary>Бренд, логотип и рекламные ссылки</summary><div class="pl-profile-grid"><label><span>Тип бренда</span><select id="plBrandMode"><option value="text" ${p.brandMode!=='image'?'selected':''}>Текстовый бренд</option><option value="image" ${p.brandMode==='image'?'selected':''} ${hasImage?'':'disabled'}>Изображение / логотип</option></select></label><label><span>Бренд</span><input id="plBrandName" value="${esc(p.brandName)}"></label><label><span>Девиз / слоган</span><input id="plTagline" value="${esc(p.tagline)}" placeholder="Оставьте пустым, чтобы не печатать"></label><label><span>Логотип из файла</span><input id="plBrandImageFile" type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml"></label></div><div class="pl-brand-image-tools">${hasImage?`<img src="${esc(p.brandImage)}" alt="Логотип"><span>Логотип загружен. Для термопринтера лучше PNG с прозрачным фоном.</span><button type="button" class="secondary" id="plRemoveBrandImage">Удалить изображение</button>`:'<span>Можно загрузить PNG/JPG/WebP/SVG. После загрузки бренд переключится на изображение.</span>'}</div><div class="pl-profile-grid"><label><span>Сайт</span><input id="plWebsite" value="${esc(p.website||PANORA_SITE)}" placeholder="https://panora.es/"></label><label><span>Instagram</span><input id="plInstagram" value="${esc(p.instagram)}" placeholder="https://instagram.com/…"></label><label><span>WhatsApp</span><input id="plWhatsapp" value="${esc(p.whatsapp)}" placeholder="+34…"></label><label><span>Ссылка акции</span><input id="plPromoUrl" value="${esc(p.promoUrl)}" placeholder="https://…"></label></div><div class="pl-profile-actions"><button type="button" class="secondary" id="plClearTagline">Убрать девиз</button><button type="button" class="secondary" id="plSaveProfile">Сохранить бренд и ссылки</button></div></details>`}
function verticalSourceHtml(){const b=bakeryProfile();return `<div class="pl-vertical-source"><strong>Вертикальная этикетка Panora · ES</strong><p>Товарные данные берутся из каталога и «Производство и безопасность». Оператор и адрес — из профиля пекарни. QR всегда ведёт на <b>panora.es</b>.</p><div><span>Оператор</span><b>${esc(b.legalName||'Не заполнен')}</b></div><div><span>Адрес</span><b>${esc(b.address||'Не заполнен')}</b></div></div>`}
let layoutUndoStack=[],layoutRedoStack=[];
let layoutStyleClipboard=null;
function layoutSnapshot(){const layout=currentLayout();return layout?structuredClone(layout):null}
function pushLayoutUndo(){const snap=layoutSnapshot();if(!snap)return;const json=JSON.stringify(snap),last=layoutUndoStack.at(-1);if(!last||last.key!==layoutKey()||last.json!==json){layoutUndoStack.push({key:layoutKey(),json,snap});if(layoutUndoStack.length>40)layoutUndoStack.shift()}layoutRedoStack=[]}
function restoreLayoutSnapshot(entry){if(!entry)return false;ensureLayouts()[entry.key]=structuredClone(entry.snap);builder.selectedBlock=preferredBlockId(ensureLayouts()[entry.key]);builder.richEditBlock='';builder.richEditProductId='';richSavedRange=null;saveBuilder();return true}
function undoLayout(){const prev=layoutUndoStack.pop();if(!prev)return;const cur=layoutSnapshot();if(cur)layoutRedoStack.push({key:layoutKey(),json:JSON.stringify(cur),snap:cur});restoreLayoutSnapshot(prev);renderLabelBuilder()}
function redoLayout(){const next=layoutRedoStack.pop();if(!next)return;const cur=layoutSnapshot();if(cur)layoutUndoStack.push({key:layoutKey(),json:JSON.stringify(cur),snap:cur});restoreLayoutSnapshot(next);renderLabelBuilder()}
function editorValue(v,digits=2){const n=Number(v);if(!Number.isFinite(n))return'';const f=10**digits;return String(Math.round(n*f)/f)}
function preferredBlockId(layout=currentLayout()){
 const blocks=layout?.blocks||{},priority=['product','price','ingredients','allergens','brand','tagline','weight','internal','producer','nutrition','qr','ean','rule'];
 for(const id of priority)if(blocks[id]&&!blocks[id]?.deleted)return id;
 return Object.keys(blocks).filter(id=>!blocks[id]?.deleted).sort((a,b)=>(Number(blocks[a]?.z)||1)-(Number(blocks[b]?.z)||1))[0]||'';
}
function ensureEditorSelection(){const layout=currentLayout();if(!layout?.blocks)return'';if(!builder.selectedBlock||!layout.blocks[builder.selectedBlock]||layout.blocks[builder.selectedBlock]?.deleted)builder.selectedBlock=preferredBlockId(layout);return builder.selectedBlock||''}
function blockPickerOptions(layout=currentLayout()){const blocks=layout?.blocks||{};return Object.entries(blocks).filter(([,b])=>!b?.deleted).sort((a,b)=>(Number(a[1]?.z)||1)-(Number(b[1]?.z)||1)).map(([id,b])=>`<option value="${esc(id)}" ${builder.selectedBlock===id?'selected':''}>${esc(b.label||id)}${b.hidden?' · скрыт':''}${b.locked?' · 🔒':''}</option>`).join('')}
