function deleteSelectedBlock(){const layout=currentLayout(),id=builder.selectedBlock,b=layout?.blocks?.[id];if(!layout||!id||!b)return;pushLayoutUndo();flushRichSave();if(b.manual===true){delete layout.blocks[id];Object.values(layout.overrides||{}).forEach(row=>{if(row&&typeof row==='object')delete row[id]})}else{b.deleted=true;b.hidden=true;b.locked=false}layout.updatedAt=new Date().toISOString();builder.selectedBlock=preferredBlockId(layout);builder.richEditBlock='';builder.richEditProductId='';richSavedRange=null;saveBuilder();renderLabelBuilder()}
function copyBlockStyle(){const b=currentLayout()?.blocks?.[builder.selectedBlock];if(!b)return;layoutStyleClipboard={fontSize:num(b.fontSize||2),fontFamily:safeFontFamily(b.fontFamily),fontWeight:Number(b.fontWeight||400),rotate:Number(b.rotate||0),textAlign:String(b.textAlign||'left'),lineHeight:num(b.lineHeight||1.15),letterSpacing:num(b.letterSpacing||0)};const btn=$('#plCopyStyle');if(btn){const old=btn.textContent;btn.textContent='Стиль скопирован';setTimeout(()=>{if(btn.isConnected)btn.textContent=old},900)}}
