function saveCurrentTemplate(){if(!currentLayout()){if(!captureLayoutFromPreview())return alert('Сначала выберите товар и создайте макет.')}const suggested=`${builder.template} ${builderDimensions().w}×${builderDimensions().h}`;const name=String(prompt('Название собственного шаблона:',suggested)||'').trim();if(!name)return;const rows=savedTemplates(),entry={id:`tpl-${Date.now()}`,name,template:builder.template,size:builder.size,customWidth:builder.customWidth,customHeight:builder.customHeight,layout:structuredClone(currentLayout()),updatedAt:new Date().toISOString()};rows.unshift(entry);write(TEMPLATE_KEY,rows.slice(0,40));renderLabelBuilder()}
