function changeLayer(mode){const b=currentLayout()?.blocks?.[builder.selectedBlock];if(!b)return;pushLayoutUndo();const z=Number(b.z)||1,max=maxLayer();if(mode==='front')b.z=max+1;else if(mode==='back')b.z=1;else if(mode==='up')b.z=z+1;else if(mode==='down')b.z=Math.max(1,z-1);currentLayout().updatedAt=new Date().toISOString();saveBuilder();renderPreview().then(()=>selectLayoutBlock(builder.selectedBlock,builder.selectedProductId))}
function duplicateSelectedBlock(){const id=builder.selectedBlock,b=currentLayout()?.blocks?.[id];if(!b)return;const source=findBlockElement($('#plPreview'),id);if(!source||!richTextEditable(id))return alert('Дублирование доступно для текстовых блоков.');pushLayoutUndo();builder.manualSeq=Math.max(0,Number(builder.manualSeq||0))+1;const newId=`manual_${builder.manualSeq}`,d=builderDimensions(),clone=structuredClone(b);clone.manual=true;clone.kind='text';clone.label=`${b.label||id} копия`;clone.html=sanitizeRichHtml(source.innerHTML);clone.x=clamp(num(b.x)+2,0,Math.max(0,d.w-num(b.w)));clone.y=clamp(num(b.y)+2,0,Math.max(0,d.h-num(b.h)));clone.z=maxLayer()+1;clone.locked=false;clone.hidden=false;currentLayout().blocks[newId]=clone;currentLayout().updatedAt=new Date().toISOString();builder.selectedBlock=newId;saveBuilder();renderLabelBuilder()}
