function removePrintWarningDialog(){document.querySelector('#plPrintWarningDialog')?.remove()}
function confirmPrintWarnings(items=[]){
 const rows=[...new Set((items||[]).map(x=>String(x||'').trim()).filter(Boolean))];
 if(!rows.length)return Promise.resolve(true);
 removePrintWarningDialog();
 return new Promise(resolve=>{
  const dialog=document.createElement('dialog');dialog.id='plPrintWarningDialog';dialog.className='pl-print-warning-dialog';
  dialog.innerHTML=`<form method="dialog" class="pl-print-warning-form"><div class="pl-print-warning-head"><div><strong>На этикетке не хватает данных</strong><small>Panora предупреждает, но не запрещает печать. Проверьте список перед продолжением.</small></div><button type="button" class="dialog-close" id="plPrintWarningClose" aria-label="Закрыть">×</button></div><div class="pl-print-warning-list"><ul>${rows.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><label class="pl-print-ignore"><input type="checkbox" id="plIgnorePrintWarnings"><span>Игнорировать предупреждения и печатать</span></label><div class="pl-print-warning-actions"><button type="button" class="secondary" id="plPrintWarningCancel">Вернуться</button><button type="button" class="primary" id="plPrintWarningProceed" disabled>Печатать</button></div></form>`;
  document.body.appendChild(dialog);
  let settled=false;const finish=value=>{if(settled)return;settled=true;try{dialog.close()}catch{}dialog.remove();resolve(Boolean(value))};
  const check=dialog.querySelector('#plIgnorePrintWarnings'),go=dialog.querySelector('#plPrintWarningProceed');
  check.onchange=()=>{go.disabled=!check.checked};
  go.onclick=()=>{if(check.checked)finish(true)};
  dialog.querySelector('#plPrintWarningCancel').onclick=()=>finish(false);
  dialog.querySelector('#plPrintWarningClose').onclick=()=>finish(false);
  dialog.addEventListener('cancel',e=>{e.preventDefault();finish(false)});
  try{dialog.showModal()}catch{const ok=window.confirm(`На этикетке не хватает данных:\n\n• ${rows.join('\n• ')}\n\nПродолжить печать?`);finish(ok)}
 });
}
async function renderPreview(){const root=$('#plPreview');if(!root)return;root.dataset.loading='1';root.innerHTML='<div class="pl-preview-empty">Готовим предпросмотр…</div>';root.innerHTML=await previewHtml();delete root.dataset.loading;await nextFrame();wireLayoutEditorPreview();const v=validationIssues(),fit=renderedFitIssues(root),box=$('#plWarnings');if(box){const blocking=[...(v.blocking||[]),...fit],confirmable=v.errors||[];box.innerHTML=blocking.length||confirmable.length||v.warnings.length?`${blocking.length?`<strong class="pl-error-title">Печать заблокирована из-за макета</strong><ul class="pl-error-list">${blocking.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${confirmable.length?`<strong class="pl-confirm-title">Не заполнены данные · можно напечатать после подтверждения</strong><ul class="pl-confirm-list">${confirmable.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${v.warnings.length?`<strong class="pl-warning-title">Проверьте</strong><ul>${v.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}`:'<span class="pl-ok">✓ Данные полные · ES готов · макет помещается</span>'}}
function collectRowsFromUi(){document.querySelectorAll('[data-label-product-row]').forEach(el=>{const id=el.dataset.labelProductRow,row=builder.products[id]||{};el.querySelectorAll('[data-pl-field]').forEach(input=>{const key=input.dataset.plField;row[key]=input.type==='checkbox'?input.checked:input.type==='number'?Math.max(1,Number(input.value||1)):input.value});builder.products[id]=row});saveBuilder()}
function history(){return read(HISTORY_KEY,[])}
function renderHistory(){const root=$('#plHistory');if(!root)return;const rows=history();root.innerHTML=rows.length?rows.slice(0,8).map((x,i)=>`<button type="button" class="pl-history-row" data-pl-history="${i}"><span>${esc(new Date(x.at).toLocaleString('es-ES'))}</span><strong>${esc(x.templateLabel)} · ${x.count} ud.</strong><small>${esc((x.products||[]).map(p=>p.name).join(', '))}</small></button>`).join(''):'<p class="pl-history-empty">Истории печати пока нет.</p>';root.querySelectorAll('[data-pl-history]').forEach(b=>b.onclick=()=>loadHistory(Number(b.dataset.plHistory)))}
