 const baseStyle=printBaseStyle(w,h);let body='';
 if(builder.paper==='a4'){const usableW=190,usableH=277,cols=Math.max(1,Math.floor(usableW/w)),rows=Math.max(1,Math.floor(usableH/h)),per=cols*rows,start=Math.max(1,Math.min(per,Number(builder.startCell||1))),cells=[...Array(start-1)].map(()=>'<div></div>'),all=[...cells,...labels];for(let i=0;i<all.length;i+=per)body+=`<section class="sheet" style="grid-template-columns:repeat(${cols},${w}mm);grid-auto-rows:${h}mm">${all.slice(i,i+per).join('')}</section>`;popup.document.write(`<title>Panora · Etiquetas · ${builder.printerType==='standard'?'Impresora estándar':'Térmica'}</title><style>@page{size:A4;margin:10mm}${baseStyle}.sheet{width:190mm;height:277mm;display:grid;align-content:start;justify-content:start;page-break-after:always}.sheet:last-child{page-break-after:auto}.sheet .pl-label{border:.2mm dashed var(--pl-ink)}</style>${body}`)}else{body=labels.map(x=>`<section class="roll-page">${x}</section>`).join('');popup.document.write(`<title>Panora · Etiquetas · ${builder.printerType==='standard'?'Impresora estándar':'Térmica'}</title><style>@page{size:${w}mm ${h}mm;margin:0}${baseStyle}.roll-page{width:${w}mm;height:${h}mm;page-break-after:always}.roll-page:last-child{page-break-after:auto}.roll-page .pl-label{border:0}</style>${body}`)}
